import React, { ReactNode, useState, useEffect, Children, isValidElement, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAnimation } from './AnimationQueue';

interface AnimatedListProps {
  children: ReactNode;
  className?: string;
  staggerDelay?: number;
  onComplete?: () => void;
  component?: 'ul' | 'ol' | 'div';
  priority?: number; // Add priority for queue
  dependencies?: string[]; // Add dependencies for queue
}

/**
 * Animated List component that renders children with staggered animations
 * Uses the animation queue system for coordinated animations
 */
const AnimatedList: React.FC<AnimatedListProps> = ({
  children,
  className = '',
  staggerDelay = 0.05,
  onComplete,
  component = 'ul',
  priority = 0,
  dependencies = []
}) => {
  const [activeItemIndex, setActiveItemIndex] = useState(-1);
  const [isComplete, setIsComplete] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  const animationIdRef = useRef<string | null>(null);

  // Get animation context
  const { registerAnimation, completeAnimation } = useAnimation();

  // Filter out empty children
  const childArray = Children.toArray(children).filter(child => 
    child !== null && 
    (typeof child !== 'string' || child.trim() !== '')
  );

  // Register with animation queue on mount
  useEffect(() => {
    if (childArray.length === 0) return;

    const handleStart = () => {
      setActiveItemIndex(-1);
      setIsComplete(false);
      setIsAnimating(true);

      // Start first item animation after a small delay
      setTimeout(() => {
        setActiveItemIndex(0);
      }, 50);
    };

    const handleComplete = () => {
      if (onComplete) {
        onComplete();
      }
    };

    // Register this animation with the queue
    const animationId = registerAnimation('list', {
      priority,
      dependencies,
      onStart: handleStart,
      onComplete: handleComplete
    });

    animationIdRef.current = animationId;

    // Clean up
    return () => {
      if (animationIdRef.current && isAnimating && !isComplete) {
        completeAnimation(animationIdRef.current);
      }
    };
  }, [childArray, priority, dependencies, registerAnimation, completeAnimation, onComplete]);

  // Handle item animation complete
  const handleItemAnimationComplete = (index: number) => {
    if (index === childArray.length - 1) {
      // All items animated
      setIsComplete(true);
      setIsAnimating(false);

      // Signal completion to the animation queue
      if (animationIdRef.current) {
        completeAnimation(animationIdRef.current);
      }
    } else {
      // Animate next item
      setActiveItemIndex(index + 1);
    }
  };

  // Add a fallback to ensure all items are shown after a timeout
  useEffect(() => {
    if (!isAnimating || isComplete) return;

    const fallbackTimer = setTimeout(() => {
      // Force completion if animation is taking too long
      setActiveItemIndex(childArray.length - 1); // Show all items
      setIsComplete(true);
      setIsAnimating(false);

      // Signal completion to the animation queue
      if (animationIdRef.current) {
        completeAnimation(animationIdRef.current);
      }
    }, 5000); // 5 second fallback

    return () => clearTimeout(fallbackTimer);
  }, [isAnimating, isComplete, childArray.length, completeAnimation]);

  // Animation variants
  const itemVariants = {
    hidden: { opacity: 0, y: 2 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.15 } }
  };

  // Create component with proper tag
  const Component = component as any;

  // Render fallback content if not animating and have children but no visible items
  if (!isAnimating && childArray.length > 0 && activeItemIndex === -1) {
    return (
      <Component 
        className={`animated-list ${className} fallback`}
        style={{
          padding: 0,
          margin: 0,
          listStyle: 'none',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'flex-start'
        }}
      >
        {childArray.map((child, index) => (
          <li
            key={index}
            style={{
              width: '100%',
              justifyContent: 'flex-start',
              listStyle: 'none'
            }}
          >
            {child}
          </li>
        ))}
      </Component>
    );
  }

  return (
    <Component 
      className={`animated-list ${className} ${isComplete ? 'complete' : ''}`}
      style={{
        padding: 0,
        margin: 0,
        listStyle: 'none',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'flex-start'
      }}
    >
      {childArray.map((child, index) => (
        <AnimatePresence key={index} mode="wait">
          {(activeItemIndex >= index || isComplete) && (
            <motion.li
              style={{
                width: '100%',
                justifyContent: 'flex-start',
                listStyle: 'none'
              }}
              initial="hidden"
              animate="visible"
              variants={itemVariants}
              onAnimationComplete={() => {
                if (activeItemIndex === index) {
                  handleItemAnimationComplete(index);
                }
              }}
            >
              {child}
            </motion.li>
          )}
        </AnimatePresence>
      ))}
    </Component>
  );
};

export default AnimatedList;
